-- Three RN1 September 2026 pilot markets. This immutable, compact audit
-- is the result of SHA-256 verified source replay, NOT estimated ROI.
-- The original private gzip pages remain intact in Supabase Storage.
-- Fee and off-API transfer information is NOT present; do not infer net profits.
create table if not exists pi.rn1_ledger_pilot_audit(
 market_key text primary key,
 title text not null,
 study_version text not null default 'pilot3_sha_verified_v1',
 first_event_at timestamptz,
 last_event_at timestamptz,
 verified_archive_pages integer not null,
 source_trade_fills integer not null,
 merge_events integer not null,
 redeem_events integer not null,
 trade_spend numeric not null,
 trade_proceeds numeric not null,
 merge_cash_in numeric not null,
 redeem_cash_in numeric not null,
 gross_cash_net numeric not null,
 residual_outcome0 numeric not null,
 residual_outcome1 numeric not null,
 minimum_intermediate_outcome0 numeric not null,
 minimum_intermediate_outcome1 numeric not null,
 trade_aggregate_reconciled boolean not null,
 activity_aggregate_reconciled boolean not null,
 intermediate_inventory_nonnegative boolean not null,
 evidence_status text not null,
 timeline jsonb not null,
 source_response_id bigint not null,
 audited_at timestamptz not null default now()
);
alter table pi.rn1_ledger_pilot_audit enable row level security;
revoke all on pi.rn1_ledger_pilot_audit from anon,authenticated;
-- Original source events can be replayed using the scheduler-authenticated,
-- read-only pi-rn1-ledger-pilot function. This snapshot is a portable
-- reproducibility artifact for the three individually selected markets.
insert into pi.rn1_ledger_pilot_audit
select * from jsonb_populate_recordset(null::pi.rn1_ledger_pilot_audit,
